+                       FeeRateEstimatorTypeToString(FeeRateEstimatorType::MEMPOOL_POLICY), NUMBER_OF_BLOCKS);
+            return false;
+        }
+        for (size_t i = 1; i < v.size(); ++i) {
+            if (v[i].m_height != v[i - 1].m_height + 1) {
+                LogWarning("%s: Non-consecutive block heights read from disk, expected height %s but found %s; ignoring file",
+                           FeeRateEstimatorTypeToString(FeeRateEstimatorType::MEMPOOL_POLICY), v[i - 1].m_height + 1, v[i].m_height);
