+            LogWarning("%s: Number of previously mined blocks read exceeds the maximum of %s; ignoring file",
+                       FeeRateEstimatorTypeToString(FeeRateEstimatorType::MEMPOOL_POLICY),
+                       MEMPOOL_HEALTH_WINDOW_BLOCKS);
+            return false;
+        }
