+    } catch (const std::exception&) {
+        LogWarning("%s: Unable to read mined-block stats from stream (non-fatal)",
+                   FeeRateEstimatorTypeToString(FeeRateEstimatorType::MEMPOOL_POLICY));
+        return false;
+    }
+    return true;
+}
